
  @font-face {
    font-family: 'Oswald';
    font-style: normal;
    font-weight: 400 700;
    font-display: swap;
    src: url(data:font/woff2;base64,) format('woff2');
  }
  @font-face {
    font-family: 'Work Sans';
    font-style: normal;
    font-weight: 300 700;
    font-display: swap;
    src: url(data:font/woff2;base64,) format('woff2');
  }

  :root {
    --paper: #e7e6da;
    --paper-2: #dedccb;
    --paper-3: #d3d1bd;
    --ink: #1e2620;
    --ink-soft: #4b564a;
    --stone: #7d7c68;
    --pine: #375340;
    --pine-soft: #cbd4c3;
    --blaze: #c1502a;
    --blaze-ink: #7a2f16;
    --sun: #e8a25c;
    --line: rgba(30, 38, 32, 0.16);
    --line-soft: rgba(30, 38, 32, 0.09);
    --shadow: rgba(30, 38, 32, 0.14);

    --font-display: 'Oswald', 'Bahnschrift', 'Arial Narrow', sans-serif;
    --font-body: 'Work Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;

    color-scheme: light;
  }

  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  html { overflow-x: hidden; }
  body {
    background: var(--paper);
    color: var(--ink);
    font-family: var(--font-body);
    font-weight: 400;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
  }
  a { color: inherit; }
  .wrap {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0 clamp(20px, 4vw, 48px);
  }

  .eyebrow {
    font-family: var(--font-display);
    font-weight: 500;
    font-size: 0.78rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--pine);
    display: inline-flex;
    align-items: center;
    gap: 0.6em;
  }
  .waymark {
    flex: none;
    width: 11px;
    height: 16px;
    border: 1px solid var(--ink);
    background: linear-gradient(to bottom, var(--paper) 0 50%, var(--blaze) 50% 100%);
  }

  h1, h2, h3 {
    font-family: var(--font-display);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.01em;
    text-wrap: balance;
    margin: 0;
    color: var(--ink);
  }

  .section-head { max-width: 62ch; }
  .section-head h2 { font-size: clamp(1.8rem, 3.4vw, 2.6rem); margin-top: 14px; }
  .section-head p { margin-top: 14px; color: var(--ink-soft); font-size: 1.02rem; max-width: 54ch; }

  /* ---------- section shell + photo backdrop ---------- */
  .section-shell { position: relative; overflow: hidden; padding: clamp(56px, 8vw, 92px) 0; }
  .section-shell > .wrap { position: relative; z-index: 1; }
  .sect-photo {
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background-size: cover;
    background-position: center;
    opacity: 0.2;
    filter: grayscale(55%) contrast(1.08) brightness(0.95);
    -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 16%, black 84%, transparent 100%);
    mask-image: linear-gradient(to bottom, transparent 0%, black 16%, black 84%, transparent 100%);
  }
  .photo-a { background-image: url(data:image/jpeg;base64,); }
  .photo-b { background-image: url(data:image/jpeg;base64,); background-position: center 65%; }
  .photo-c { background-image: url(data:image/jpeg;base64,); background-position: center 65%; }
  .photo-d { background-image: url(data:image/jpeg;base64,); background-position: center 35%; }

  .tone-2 { background: var(--paper-2); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }

  /* ---------- nav ---------- */
  header { position: relative; z-index: 2; border-bottom: 1px solid var(--line); background: var(--paper); }
  nav.wrap { display: flex; align-items: center; justify-content: space-between; padding-top: 20px; padding-bottom: 20px; gap: 24px; }
  .brand { display: flex; align-items: center; gap: 10px; font-family: var(--font-display); font-weight: 600; font-size: 1.7rem; letter-spacing: 0.03em; text-decoration: none; }
  .brand svg { flex: none; }
  .brand-text { display: flex; flex-direction: column; line-height: 1.1; }
  .brand-text .domain { color: var(--blaze); font-weight: 500; }
  .brand-text small {
    margin-top: 3px; font-family: var(--font-body); font-weight: 400; font-size: 0.62rem;
    letter-spacing: 0.02em; text-transform: none; color: var(--stone);
  }
  .navlinks { display: flex; gap: 28px; list-style: none; margin: 0; padding: 0; font-size: 0.92rem; color: var(--ink-soft); }
  .navlinks a { text-decoration: none; }
  .navlinks a:hover { color: var(--pine); }
  .navcta { display: flex; align-items: center; gap: 18px; flex: none; }
  .navcta .ghostlink { font-size: 0.92rem; text-decoration: none; color: var(--ink-soft); white-space: nowrap; }
  @media (max-width: 860px) { .navlinks { display: none; } }
  @media (max-width: 480px) {
    .navcta { gap: 12px; }
    .navcta .ghostlink { display: none; }
    .navcta .btn { padding: 0.7em 1.05em; font-size: 0.78rem; }
  }

  /* ---------- buttons / pills / links ---------- */
  .btn {
    display: inline-flex; align-items: center; gap: 0.5em;
    font-family: var(--font-display); font-weight: 500; font-size: 0.9rem; letter-spacing: 0.06em; text-transform: uppercase;
    text-decoration: none; padding: 0.85em 1.5em; border-radius: 3px; white-space: nowrap;
    transition: transform 0.15s ease;
  }
  .btn-primary { background: var(--blaze); color: #fbf3ec; box-shadow: 0 2px 0 var(--blaze-ink); }
  .btn-primary:hover { transform: translateY(-1px); }
  .btn-outline { background: transparent; color: var(--ink); border: 1.5px solid var(--ink); }
  .btn-outline:hover { border-color: var(--pine); color: var(--pine); }

  .pill {
    display: inline-flex; align-items: center; padding: 0.32em 0.8em; border: 1px solid var(--pine); color: var(--pine);
    font-family: var(--font-display); font-size: 0.68rem; letter-spacing: 0.08em; text-transform: uppercase;
  }
  .pill.stamp { border: 1.5px dashed var(--blaze); color: var(--blaze); transform: rotate(-3deg); }

  .textlink {
    font-family: var(--font-display); font-size: 0.85rem; letter-spacing: 0.04em; text-transform: uppercase;
    text-decoration: none; color: var(--pine); display: inline-flex; align-items: center; gap: 0.4em;
  }
  .textlink::after { content: "→"; }

  /* ---------- hero ---------- */
  .hero { position: relative; padding: clamp(52px, 8vw, 96px) 0 clamp(60px, 8vw, 100px); overflow: hidden; }
  .hero-grid { position: relative; z-index: 1; display: grid; grid-template-columns: 1.05fr 0.95fr; gap: clamp(32px, 6vw, 64px); align-items: center; }
  @media (max-width: 900px) { .hero-grid { grid-template-columns: 1fr; } }
  .hero h1 { font-size: clamp(2.6rem, 6.4vw, 4.4rem); line-height: 0.98; margin-top: 18px; }
  .hero-copy { margin-top: 22px; max-width: 46ch; font-size: 1.08rem; color: var(--ink-soft); }
  .hero-actions { margin-top: 32px; display: flex; gap: 16px; flex-wrap: wrap; }
  .hero-tags { margin-top: 34px; display: flex; gap: 22px; flex-wrap: wrap; font-size: 0.82rem; color: var(--stone); }
  .hero-tags span { display: inline-flex; align-items: center; gap: 0.5em; }
  .hero-tags span::before { content: ""; width: 6px; height: 6px; background: var(--pine); border-radius: 50%; }

  .hero-glow {
    position: absolute; z-index: 0; right: 6%; top: 8%; width: 320px; height: 320px; border-radius: 50%;
    background: radial-gradient(circle, var(--sun) 0%, transparent 70%); opacity: 0.3; filter: blur(6px); pointer-events: none;
  }
  .hero-scrim {
    position: absolute; inset: 0; z-index: 0; pointer-events: none;
    background: linear-gradient(100deg, var(--paper) 0%, var(--paper) 26%, transparent 68%);
  }
  .geo-tag {
    position: absolute; right: clamp(20px, 4vw, 48px); bottom: 22px; z-index: 1;
    font-family: var(--font-display); font-size: 0.72rem; letter-spacing: 0.08em; color: var(--ink-soft);
    font-variant-numeric: tabular-nums; text-transform: uppercase;
  }
  @media (max-width: 720px) { .geo-tag { display: none; } }

  /* ---------- notebook / refuge card ---------- */
  .card {
    position: relative; background: var(--paper-2); border: 1px solid var(--line); padding: clamp(22px, 3vw, 28px);
    clip-path: polygon(0% 1.2%, 2% 0%, 98% 0.4%, 100% 1.6%, 99.4% 98.2%, 97.7% 100%, 2.3% 99.6%, 0.6% 98%);
    box-shadow: 0 18px 40px -22px var(--shadow);
  }
  .card-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
  .card-eyebrow { font-family: var(--font-display); font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--stone); }
  .card-title { font-family: var(--font-display); font-size: 1.5rem; text-transform: uppercase; margin-top: 4px; letter-spacing: 0.01em; }

  .card-sub {
    margin-top: 18px; padding-top: 16px; border-top: 1px dashed var(--line);
    display: flex; justify-content: space-between; align-items: flex-start; gap: 12px;
  }
  .card-sub-title { font-family: var(--font-display); font-size: 1.15rem; text-transform: uppercase; margin-top: 4px; }
  .card-desc { margin-top: 10px; font-size: 0.92rem; color: var(--ink-soft); }
  .card-meta { margin-top: 4px; font-size: 0.8rem; color: var(--stone); }

  .elev-wrap { margin-top: 16px; }
  .elev-cap { font-family: var(--font-display); font-size: 0.68rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--stone); }
  .elev-wrap svg { width: 100%; height: auto; display: block; margin-top: 4px; }
  .elev-path { fill: none; stroke: var(--pine); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  .elev-fill { fill: var(--pine-soft); opacity: 0.6; }
  .elev-peak { fill: var(--blaze); }

  .stat-row { margin-top: 16px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); }
  .stat { background: var(--paper-2); padding: 12px 6px; text-align: center; }
  .stat b { display: block; font-family: var(--font-display); font-size: 1.3rem; font-variant-numeric: tabular-nums; letter-spacing: 0.01em; }
  .stat span { font-size: 0.66rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--stone); }

  .progress { margin-top: 16px; }
  .progress-label { display: flex; justify-content: space-between; font-size: 0.72rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--stone); margin-bottom: 6px; }
  .progress-label b { color: var(--ink); font-variant-numeric: tabular-nums; }
  .progress-bar { height: 6px; background: var(--paper-3); overflow: hidden; }
  .progress-bar span { display: block; height: 100%; width: 33%; background: var(--blaze); }

  .card-foot { margin-top: 14px; display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
  .card-foot div { flex: 1; min-width: 140px; }
  .card-foot .label { display: block; color: var(--stone); letter-spacing: 0.06em; text-transform: uppercase; font-size: 0.64rem; margin-bottom: 2px; }
  .card-foot .value { font-family: var(--font-display); font-size: 0.9rem; text-transform: uppercase; color: var(--ink); }

  /* ---------- ridge divider ---------- */
  .divider { display: block; width: 100%; height: auto; }
  .divider .d-near { fill: var(--pine); }
  .divider .d-far { fill: var(--pine-soft); }

  /* ---------- feature grid (bordered, any column count) ---------- */
  .feature-grid { margin-top: 44px; display: grid; border-top: 1px solid var(--line); border-left: 1px solid var(--line); }
  .feature-grid.cols-5 { grid-template-columns: repeat(5, 1fr); }
  @media (max-width: 1040px) { .feature-grid.cols-5 { grid-template-columns: repeat(3, 1fr); } }
  @media (max-width: 640px) { .feature-grid.cols-5 { grid-template-columns: 1fr; } }
  .feature { padding: 24px 22px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
  .feature svg { color: var(--pine); }
  .feature h3 { margin-top: 16px; font-size: 1.08rem; }
  .feature p { margin-top: 8px; color: var(--ink-soft); font-size: 0.92rem; max-width: 32ch; }

  /* ---------- statement (positionnement) ---------- */
  .statement .wrap { max-width: 780px; }
  .statement h2 { font-size: clamp(1.9rem, 4vw, 2.8rem); margin-top: 14px; }
  .statement p { margin-top: 18px; color: var(--ink-soft); font-size: 1.05rem; max-width: 62ch; }

  /* ---------- itinerary (comment ça marche) ---------- */
  .itinerary { margin-top: 44px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
  .step { display: flex; gap: clamp(18px, 3vw, 32px); padding: 22px 0; border-bottom: 1px solid var(--line); align-items: flex-start; }
  .step:last-child { border-bottom: none; }
  .step-num { font-family: var(--font-display); font-size: 2rem; color: var(--pine); flex: none; width: 2.4ch; font-variant-numeric: tabular-nums; }
  .step-body h3 { font-size: 1.1rem; }
  .step-body p { margin-top: 6px; color: var(--ink-soft); font-size: 0.95rem; max-width: 56ch; }

  /* ---------- sommets two-col ---------- */
  .sommet-grid { margin-top: 40px; display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: stretch; }
  @media (max-width: 820px) { .sommet-grid { grid-template-columns: 1fr; } }
  .vivant { border: 1px solid var(--line); padding: clamp(20px, 3vw, 28px); display: flex; flex-direction: column; justify-content: space-between; }
  .vivant p { font-size: 1.02rem; color: var(--ink); }
  .vivant .stat-row { margin-top: 20px; }

  /* ---------- collection legend ---------- */
  .legend-row { margin-top: 40px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
  @media (max-width: 720px) { .legend-row { grid-template-columns: 1fr; } }
  .legend-icon { width: 32px; height: 32px; border-radius: 50%; flex: none; }
  .legend-icon.discover { border: 2px dashed var(--line); }
  .legend-icon.reveal { border: 2px solid var(--pine); }
  .legend-icon.validate { border: 2px solid var(--pine); background: var(--pine); }
  .legend-item h3 { margin-top: 14px; font-size: 1.02rem; }
  .legend-item p { margin-top: 6px; color: var(--ink-soft); font-size: 0.9rem; }

  .stamp-cap { margin-top: 48px; display: flex; justify-content: space-between; align-items: flex-end; gap: 24px; flex-wrap: wrap; }
  .stamp-cap .count { font-family: var(--font-display); font-size: 0.85rem; letter-spacing: 0.06em; color: var(--stone); text-transform: uppercase; }
  .stamp-cap .count b { color: var(--ink); font-variant-numeric: tabular-nums; }
  .stamp-grid { margin-top: 22px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
  @media (max-width: 720px) { .stamp-grid { grid-template-columns: repeat(2, 1fr); } }
  .stamp-disc {
    aspect-ratio: 1; border-radius: 50%; display: flex; flex-direction: column; align-items: center; justify-content: center;
    text-align: center; padding: 14px; border: 2px solid var(--pine); color: var(--ink);
  }
  .stamp-disc.pending { border-style: dashed; border-color: var(--line); color: var(--stone); }
  .stamp-disc b { font-family: var(--font-display); font-size: 0.95rem; text-transform: uppercase; letter-spacing: 0.01em; line-height: 1.1; }
  .stamp-disc span { margin-top: 6px; font-size: 0.7rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--stone); }
  .stamp-disc.done span { color: var(--blaze); }

  /* ---------- progression personnelle ---------- */
  .stat-row-4 { margin-top: 40px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); }
  @media (max-width: 720px) { .stat-row-4 { grid-template-columns: repeat(2, 1fr); } }
  .stat-row-4 .stat { padding: 22px 10px; }
  .stat-row-4 .stat b { font-size: 1.9rem; }

  .objective { margin-top: 24px; border: 1px solid var(--line); padding: clamp(18px, 3vw, 24px); display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 20px; }
  .objective-label { font-family: var(--font-display); font-size: 0.95rem; text-transform: uppercase; letter-spacing: 0.02em; }
  .objective-label span { display: block; margin-top: 3px; font-family: var(--font-body); font-size: 0.8rem; color: var(--stone); text-transform: none; letter-spacing: normal; }
  .objective .stat-row { margin-top: 0; flex: none; width: min(320px, 100%); }

  /* ---------- cta ---------- */
  .cta { text-align: left; }
  .cta h2 { font-size: clamp(2.1rem, 5vw, 3.2rem); max-width: 20ch; margin-top: 16px; }
  .cta p { margin-top: 16px; color: var(--ink-soft); max-width: 48ch; font-size: 1.04rem; }
  .cta-actions { margin-top: 30px; display: flex; gap: 16px; flex-wrap: wrap; }

  /* ---------- footer ---------- */
  footer { border-top: 1px solid var(--line); padding: 34px 0 44px; }
  .foot-row { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
  .foot-brand { display: flex; align-items: center; gap: 10px; font-family: var(--font-display); font-size: 1rem; letter-spacing: 0.04em; text-transform: uppercase; }
  .foot-links { display: flex; gap: 24px; list-style: none; margin: 0; padding: 0; font-size: 0.85rem; color: var(--ink-soft); }
  .foot-links a { text-decoration: none; }
  .foot-note { margin-top: 18px; font-size: 0.78rem; color: var(--stone); }

  .note-banner {
    background: var(--pine); color: var(--paper); font-family: var(--font-display); font-size: 0.78rem;
    letter-spacing: 0.08em; text-transform: uppercase; text-align: center; padding: 9px 12px;
  }


  /* ---------- HOVREN refinement pass by ChatGPT ---------- */
  :root {
    --paper: #f3f0e3;
    --paper-2: #ebe7d4;
    --paper-3: #d9d4be;
    --ink: #18231b;
    --ink-soft: #53604f;
    --stone: #78806e;
    --pine: #294d38;
    --pine-deep: #0f2d22;
    --pine-soft: #dce7d6;
    --mint: #d7eadb;
    --blaze: #c4512a;
    --blaze-ink: #7f2f18;
    --sun: #e6ad75;
    --line: rgba(24, 35, 27, 0.15);
    --line-soft: rgba(24, 35, 27, 0.08);
    --shadow: rgba(24, 35, 27, 0.20);
  }

  body {
    background:
      radial-gradient(circle at 18% 0%, rgba(255, 248, 224, 0.28), transparent 28%),
      linear-gradient(180deg, #f3f0e3 0%, #eee9d8 48%, #f3f0e3 100%);
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 20;
    opacity: 0.12;
    mix-blend-mode: multiply;
    background-image:
      radial-gradient(circle at 1px 1px, rgba(24, 35, 27, 0.18) 1px, transparent 0);
    background-size: 18px 18px;
  }

  .note-banner { display: none !important; }

  header {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 30;
    background: rgba(246, 242, 229, 0.88);
    backdrop-filter: blur(18px) saturate(1.15);
    -webkit-backdrop-filter: blur(18px) saturate(1.15);
    border-bottom: 1px solid rgba(41, 77, 56, 0.14);
  }
  main { padding-top: 83px; }

  nav.wrap { padding-top: 18px; padding-bottom: 18px; }
  .brand { color: var(--ink); gap: 12px; }
  .brand svg { color: var(--pine); }
  .brand-text small { color: #6d745f; }
  .brand-name { letter-spacing: 0.04em; }
  .brand-text .domain { color: var(--blaze); font-weight: 700; letter-spacing: 0.01em; }
  .navlinks { color: #596453; }
  .navlinks a { transition: color 180ms ease; }
  .navlinks a:hover { color: var(--pine-deep); }
  .navcta .ghostlink { color: #4e5a4d; }

  .btn {
    border-radius: 8px;
    transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease, border-color 180ms ease;
  }
  .btn:hover { transform: translateY(-1px); }
  .btn-primary {
    background: linear-gradient(180deg, #c85a34 0%, #b84824 100%);
    border-color: rgba(109, 42, 20, 0.42);
    box-shadow: 0 12px 28px -18px rgba(196, 81, 42, 0.9), inset 0 1px 0 rgba(255,255,255,.16);
  }
  .btn-primary:hover { background: linear-gradient(180deg, #d16039 0%, #ad3f1f 100%); }
  .btn-outline {
    background: rgba(246, 242, 229, 0.42);
    border-color: rgba(24, 35, 27, 0.48);
    box-shadow: inset 0 1px 0 rgba(255,255,255,.20);
  }

  .hero {
    min-height: calc(100svh - 80px);
    display: grid;
    align-items: center;
    padding: clamp(56px, 7vw, 88px) 0 clamp(72px, 8vw, 108px);
    background:
      linear-gradient(180deg, rgba(246,242,229,.98) 0%, rgba(238,233,216,.94) 72%, rgba(235,231,212,.98) 100%);
  }
  .hero::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 0;
    height: clamp(150px, 18vw, 260px);
    pointer-events: none;
    background:
      linear-gradient(180deg, rgba(235,231,212,0) 0%, rgba(235,231,212,.76) 62%, #ebe7d4 100%);
  }
  .hero .sect-photo {
    opacity: 0.24;
    filter: grayscale(24%) saturate(0.92) contrast(0.96) brightness(1.04);
    transform: scale(1.02);
    background-position: center 40%;
    -webkit-mask-image: linear-gradient(to bottom, black 0%, black 82%, transparent 100%);
    mask-image: linear-gradient(to bottom, black 0%, black 82%, transparent 100%);
  }
  .hero-scrim {
    background:
      linear-gradient(100deg, rgba(246,242,229,0.94) 0%, rgba(246,242,229,0.86) 34%, rgba(246,242,229,0.54) 68%, rgba(246,242,229,0.72) 100%),
      radial-gradient(circle at 78% 28%, rgba(196, 81, 42, 0.10), transparent 30%);
  }
  .hero-glow {
    right: 17%;
    top: 12%;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(196, 81, 42, 0.28) 0%, rgba(196, 81, 42, 0.10) 38%, transparent 72%);
    opacity: 0.62;
    filter: blur(20px);
  }
  .hero h1 {
    max-width: 9.8ch;
    font-size: clamp(3.1rem, 7vw, 5.65rem);
    line-height: 0.92;
    letter-spacing: 0.006em;
  }
  .hero-grid > :first-child { transform: translateY(6px); }
  .hero-copy { color: #505b4d; font-size: clamp(1rem, 1.4vw, 1.13rem); }
  .hero-origin {
    margin: 18px 0 0;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: rgba(41, 77, 56, 0.72);
    font-size: 0.82rem;
    letter-spacing: 0.01em;
  }
  .hero-origin svg {
    flex: none;
    color: rgba(41, 77, 56, 0.68);
  }
  .hero-tags { color: #6a735f; }
  .hero-tags span::before { background: var(--pine); box-shadow: 0 0 0 4px rgba(41,77,56,.08); }
  .geo-tag { color: rgba(41,77,56,.55); }

  .card {
    clip-path: none;
    border-radius: 18px;
    background:
      linear-gradient(145deg, rgba(246,242,229,0.84), rgba(225,221,199,0.92)),
      var(--paper-2);
    border: 1px solid rgba(41, 77, 56, 0.18);
    box-shadow: 0 26px 70px -42px rgba(24, 35, 27, 0.62), inset 0 1px 0 rgba(255,255,255,0.42);
    overflow: hidden;
  }
  .hero .card {
    max-width: 535px;
    margin-left: auto;
    transform: rotate(-0.45deg);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
  }
  .hero .card::before {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background:
      radial-gradient(circle at 85% 16%, rgba(196,81,42,.09), transparent 28%),
      radial-gradient(circle at 10% 100%, rgba(41,77,56,.12), transparent 38%);
  }
  .card > * { position: relative; z-index: 1; }
  .card-sub { border-top-color: rgba(41,77,56,.20); }
  .card-title { color: var(--ink); }
  .card-desc { color: #485545; }
  .card-meta { color: #747b69; }

  .pill {
    border-radius: 999px;
    padding: 0.42em 0.78em;
    background: rgba(41,77,56,.08);
    border-color: rgba(41,77,56,.20);
    color: var(--pine);
  }
  .pill.stamp {
    border-radius: 7px;
    background: rgba(196,81,42,.07);
    transform: rotate(-4deg);
    box-shadow: 0 8px 18px -18px rgba(196,81,42,.7);
  }
  .elev-fill { fill: rgba(41, 77, 56, 0.14); opacity: 1; }
  .elev-path { stroke: var(--pine); stroke-width: 2.7; }
  .hero .card .elev-wrap { margin-top: 12px; }
  .progress-bar { border-radius: 999px; background: rgba(41,77,56,.13); }
  .progress-bar span { border-radius: inherit; background: linear-gradient(90deg, var(--blaze), #d89853); }

  .stat-row,
  .stat-row-4 {
    gap: 0;
    background: transparent;
    border: 1px solid rgba(41,77,56,.16);
    border-radius: 10px;
    overflow: hidden;
  }
  .stat {
    background: rgba(246, 242, 229, 0.52);
    border-right: 1px solid rgba(41,77,56,.12);
  }
  .stat:last-child { border-right: none; }
  .hero .card .stat { padding: 9px 6px 10px; }
  .hero .card .stat b { line-height: 0.96; }
  .hero .card .stat span { display: block; margin-top: 3px; line-height: 1; }

  .divider .d-near { fill: rgba(41,77,56,.82); }
  .divider .d-far { fill: rgba(203,212,195,.92); }
  .divider { background: #ebe7d4; }

  .section-shell { padding: clamp(64px, 8vw, 104px) 0; }
  .section-shell { background: #f3f0e3; }
  .sect-photo { opacity: 0.105; filter: grayscale(40%) saturate(0.85) contrast(0.92) brightness(1.08); }
  .tone-2 {
    background:
      radial-gradient(circle at 80% 20%, rgba(41,77,56,.08), transparent 30%),
      #ebe7d4;
  }

  .feature-grid {
    border: 0;
    gap: 18px;
  }
  .feature {
    border: 1px solid rgba(41,77,56,.14);
    border-radius: 18px;
    background: rgba(255,255,255,.34);
    box-shadow: 0 22px 54px -46px rgba(24,35,27,.44);
    transition:
      transform 190ms ease,
      border-color 190ms ease,
      box-shadow 190ms ease,
      background 190ms ease;
    transform-origin: center;
  }
  .feature p { color: #525d51; }
  @media (hover: hover) and (pointer: fine) {
    .feature:hover {
      transform: translateY(-6px) scale(1.018);
      border-color: rgba(41,77,56,.24);
      background: rgba(255,255,255,.44);
      box-shadow: 0 30px 70px -48px rgba(24,35,27,.58);
    }
  }
  @media (prefers-reduced-motion: reduce) {
    .feature { transition: none; }
    .feature:hover { transform: none; }
  }

  .statement .wrap {
    max-width: 1040px;
    padding-top: clamp(32px, 5vw, 58px);
    padding-bottom: clamp(32px, 5vw, 58px);
    border: 1px solid rgba(41,77,56,.14);
    border-radius: 24px;
    background: linear-gradient(135deg, rgba(255,255,255,.36), rgba(235,231,212,.64));
    box-shadow: 0 30px 80px -62px rgba(24,35,27,.58);
  }

  .itinerary {
    border: 0;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
  }
  .step {
    border: 1px solid rgba(41,77,56,.14);
    border-radius: 18px;
    padding: 22px;
    background: rgba(255,255,255,.30);
    display: block;
    transition:
      transform 190ms ease,
      border-color 190ms ease,
      box-shadow 190ms ease,
      background 190ms ease;
    transform-origin: center;
  }
  .step-num { display: block; margin-bottom: 16px; color: rgba(41,77,56,.62); }
  @media (hover: hover) and (pointer: fine) {
    .step:hover {
      transform: translateY(-6px) scale(1.018);
      border-color: rgba(41,77,56,.24);
      background: rgba(255,255,255,.40);
      box-shadow: 0 28px 66px -50px rgba(24,35,27,.56);
    }
  }
  @media (prefers-reduced-motion: reduce) {
    .step { transition: none; }
    .step:hover { transform: none; }
  }
  @media (max-width: 980px) { .itinerary { grid-template-columns: repeat(2, 1fr); } }
  @media (max-width: 640px) { .itinerary { grid-template-columns: 1fr; } }

  .sommet-grid { grid-template-columns: 1.05fr .95fr; }
  .sommet-grid > .card {
    min-height: 320px;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    color: #f8f4e8;
    background:
      linear-gradient(180deg, rgba(12, 27, 20, 0.10), rgba(12, 27, 20, 0.78)),
      radial-gradient(circle at 76% 18%, rgba(255,246,220,.16), transparent 30%),
      var(--paper-2);
    border-color: rgba(255,255,255,.22);
  }
  .summit-card-photo {
    position: absolute !important;
    inset: 0;
    z-index: 0 !important;
    background-image: url('/landing/summit-discovery-wildflowers.jpg');
    background-size: cover;
    background-position: center 74%;
    opacity: .78;
    filter: saturate(.9) contrast(.98) brightness(.92);
    transform: scale(1.02);
  }
  .sommet-grid > .card::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background:
      linear-gradient(180deg, rgba(11, 25, 18, 0.06), rgba(11, 25, 18, 0.30) 42%, rgba(11, 25, 18, 0.78)),
      linear-gradient(90deg, rgba(11, 25, 18, 0.72), rgba(11, 25, 18, 0.14) 62%, rgba(11, 25, 18, 0.28));
  }
  .sommet-grid > .card > :not(.summit-card-photo) {
    position: relative;
    z-index: 1;
  }
  .sommet-grid > .card .card-title,
  .sommet-grid > .card .card-meta,
  .sommet-grid > .card .card-eyebrow { color: inherit; }
  .sommet-grid > .card .pill { background: rgba(255,255,255,.14); border-color: rgba(255,255,255,.22); color: #fff7e8; }
  .sommet-grid > .card .textlink { color: #fff7e8; }
  .vivant {
    border-radius: 18px;
    background: rgba(255,255,255,.30);
    border-color: rgba(41,77,56,.14);
  }
  .vivant p { font-size: clamp(1.2rem, 2.5vw, 1.8rem); font-family: var(--font-display); text-transform: uppercase; line-height: 1.05; }

  .legend-item {
    border-left: 1px solid rgba(41,77,56,.16);
    padding-left: 22px;
  }
  .stamp-disc { background: rgba(255,255,255,.24); box-shadow: inset 0 1px 0 rgba(255,255,255,.35); }
  .stamp-disc.done { background: rgba(41,77,56,.08); }

  .objective {
    border-radius: 18px;
    background: rgba(255,255,255,.28);
    border-color: rgba(41,77,56,.14);
  }
  .cta .wrap {
    max-width: 1040px;
    padding-top: clamp(36px, 6vw, 68px);
    padding-bottom: clamp(36px, 6vw, 68px);
    border-radius: 24px;
    background: linear-gradient(135deg, rgba(41,77,56,.10), rgba(235,231,212,.52));
    border: 1px solid rgba(41,77,56,.14);
  }

  footer { background: rgba(235,231,216,.70); }
  .foot-links { align-items: center; }
  .social-link {
    width: 34px;
    height: 34px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(41,77,56,.16);
    border-radius: 999px;
    color: rgba(41,77,56,.76);
    background: rgba(255,255,255,.24);
    transition: transform 160ms ease, color 160ms ease, border-color 160ms ease, background 160ms ease;
  }
  .social-link:hover {
    transform: translateY(-1px);
    color: var(--pine);
    border-color: rgba(41,77,56,.28);
    background: rgba(255,255,255,.38);
  }

  @media (max-width: 900px) {
    .hero h1 { max-width: 12ch; }
    .hero .card { margin-left: 0; transform: none; }
  }
  @media (max-width: 560px) {
    .hero { min-height: auto; }
    .hero h1 { font-size: clamp(2.8rem, 16vw, 4.3rem); }
    .hero-actions .btn { width: 100%; justify-content: center; }
    .card-sub { flex-direction: column; }
    .stat-row, .stat-row-4 { grid-template-columns: 1fr; }
    .stat { border-right: 0; border-bottom: 1px solid rgba(41,77,56,.12); }
    .stat:last-child { border-bottom: 0; }
    .stamp-grid { gap: 12px; }
